import { useState, useEffect, useCallback } from 'react';
import debounce from 'lodash/debounce';

const useTableFilters = (defaultOrderBy = 'id', defaultOrder = 'asc', debounceDelay = 500) => {
    const [searchQuery, setSearchQuery] = useState(''); // ✅ Used for API calls (debounced)
    const [order, setOrder] = useState(defaultOrder);
    const [orderBy, setOrderBy] = useState(defaultOrderBy);

    // ✅ Debounce API call (updates `searchQuery` only after delay)
    const debouncedSearch = useCallback(
        debounce((query) => {
            setSearchQuery(query.toLowerCase());
        }, debounceDelay),
        [debounceDelay]
    );

    // ✅ Cleanup debounce function on unmount
    useEffect(() => () => debouncedSearch.cancel(), [debouncedSearch]);

    // ✅ Pass debounced search function to be used in the component
    const handleSearch = (query) => {
        debouncedSearch(query); // ✅ Call API after debounce delay
    };

    const handleRequestSort = (property) => {
        setOrderBy((prevOrderBy) => {
            let newOrder;
            if (prevOrderBy === property) {
                setOrder((prevOrder) => (prevOrder === 'asc' ? 'desc' : 'asc'));
            } else {
                newOrder = 'asc';
                setOrder(newOrder);
            }
            return property;
        });
    };

    return { searchQuery, order, orderBy, handleSearch, handleRequestSort };
};

export default useTableFilters;
